#!/usr/bin/expect -f
set timeout 1
set extension_path "/tmp/sanitized/extensions/powerline-extension-with-a-deliberately-long-file-name.ts"
set agent_dir "/tmp/sanitized/agent"
set work_dir "/tmp/sanitized/work"
set log_path "/tmp/sanitized/output.ansi"
file delete -force $agent_dir $work_dir
file mkdir $agent_dir $work_dir
set settings [open "$agent_dir/settings.json" w]
puts $settings {{"powerline":{"preset":"ascii","placement":"above","welcome":{"enabled":false},"segments":{"primary":["model","tokens","cost"],"secondary":["session"]}},"lastChangelogVersion":"0.84.4"}}
close $settings
cd $work_dir
log_file -noappend $log_path
spawn env TERM=xterm-256color COLORTERM=truecolor COLUMNS=44 LINES=30 PI_OFFLINE=1 PI_CODING_AGENT_DIR=$agent_dir pi --no-session --no-context-files --no-prompt-templates --no-themes --no-extensions --no-skills -e $extension_path
stty columns 44 rows 30
set deadline [expr {[clock milliseconds] + 8000}]
set ready 0
while {[clock milliseconds] < $deadline} {
  expect {
    "\033\[c" { send "\033\[?1;2c"; exp_continue -continue_timer }
    "\033\[?u" { send "\033\[?0u"; exp_continue -continue_timer }
    "Trust project folder?" { puts stderr "unexpected trust prompt"; exit 1 }
    -re {0/1\.0M} { set ready 1; break }
    timeout {}
  }
}
if {!$ready} { puts stderr "not ready"; exit 1 }
send -- "/help\r"
after 800
send -- "\033\[B\r"
puts "NARROW_CREATE_DONE"
close
exit 0
